import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CZo9GF0W.js";const u=JSON.parse('{"title":"Neon","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/neon.md","filePath":"recipes/neon.md","lastUpdated":1789060268000}'),r={name:"recipes/neon.md"};function s(d,e,i,c,h,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="neon" tabindex="-1">Neon <a class="header-anchor" href="#neon" aria-label="Permalink to &quot;Neon&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>ep-cool-name-123456.eu-central-1.aws.neon.tech</code></td></tr><tr><td>Port</td><td><code>5432</code></td></tr><tr><td>Database</td><td><code>neondb</code>, or your own</td></tr><tr><td>User</td><td><code>neondb_owner</code>, or your own</td></tr><tr><td>Password</td><td>from the Neon console</td></tr><tr><td>SSL mode</td><td><code>verify-full</code> — Neon <strong>requires</strong> TLS and will refuse a plaintext connection</td></tr><tr><td>Environment</td><td>by branch: <code>prod</code> for main, <code>dev</code> for a development branch</td></tr></tbody></table><p>The connection string in the console is a URI; paste it into the host field and Pitta splits it across the form, moving the password straight into the keychain.</p><h2 id="branches-are-separate-connections" tabindex="-1">Branches are separate connections <a class="header-anchor" href="#branches-are-separate-connections" aria-label="Permalink to &quot;Branches are separate connections&quot;">​</a></h2><p>Each Neon branch has its own endpoint host. Make one profile per branch you work with, and tag them differently — that is what makes the production branch turn red and ask for a typed confirmation while a dev branch does not.</p><h2 id="pooled-versus-direct-endpoints" tabindex="-1">Pooled versus direct endpoints <a class="header-anchor" href="#pooled-versus-direct-endpoints" aria-label="Permalink to &quot;Pooled versus direct endpoints&quot;">​</a></h2><p>Neon&#39;s pooled endpoint has <code>-pooler</code> in the host name and is PgBouncer in transaction mode. It does not support prepared statements, session state or cursors, and Pitta pages the grid with a cursor.</p><p><strong>Use the direct (non-pooled) endpoint.</strong> The pooled one is for your application&#39;s connection storm, not for an interactive client.</p><h2 id="scale-to-zero" tabindex="-1">Scale-to-zero <a class="header-anchor" href="#scale-to-zero" aria-label="Permalink to &quot;Scale-to-zero&quot;">​</a></h2><p>A Neon compute that has scaled to zero takes a few hundred milliseconds to a few seconds to wake. The first query after an idle period is slow and occasionally times out; raise the profile&#39;s connect timeout if it bites.</p><p>Pitta holds a pool open while a connection is open, which keeps the compute awake and consumes compute time. Disconnect the profile when you are done, if that matters to your bill.</p><h2 id="endpoint-in-options" tabindex="-1"><code>endpoint</code> in options <a class="header-anchor" href="#endpoint-in-options" aria-label="Permalink to &quot;`endpoint` in options&quot;">​</a></h2><p>If you are connecting through a host name that does not carry the endpoint ID — some proxies, some older setups — Neon needs the endpoint passed as an option instead. Put it in the profile&#39;s connection options as <code>endpoint=ep-cool-name-123456</code>. With the normal endpoint host name this is not needed.</p>',13)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
